"""Tests for MocapSourceService: reading saved worker outputs (written here in the same format as the worker writes
them), describing them and checking them for the face, body and audio roles."""

import json
import os
import sys

import numpy as np
import pytest

from .. import dynamic_import

MocapSourceService = dynamic_import("mpfb.services.mocapsourceservice", "MocapSourceService")
_MODULE = sys.modules[MocapSourceService.__module__]
ROLE_FACE, ROLE_BODY, ROLE_AUDIO = _MODULE.ROLE_FACE, _MODULE.ROLE_BODY, _MODULE.ROLE_AUDIO
ERROR, WARNING = _MODULE.ERROR, _MODULE.WARNING


def _run_dir(tmp_path, name="20261023_101418"):
    path = tmp_path / name
    path.mkdir()
    return path


def _write_vision(run_dir, frames=60, fps=30.0, face_frames=None, pose_frames=None, face_enabled=True, name="front"):
    """A *_landmarks.npz like the worker writes it, with NaN where nothing was detected."""
    face_frames = frames if face_frames is None else face_frames
    pose_frames = frames if pose_frames is None else pose_frames
    pose = np.zeros((frames, 33, 5), dtype=np.float32)
    pose[pose_frames:] = np.nan
    blendshapes = np.full((frames, 52), 0.1, dtype=np.float32)
    blendshapes[face_frames:] = np.nan
    hands = np.full((frames, 2, 21, 3), np.nan, dtype=np.float32)
    times = np.round(np.arange(frames) * 1000.0 / fps).astype(np.int64)
    path = run_dir / ("video_%s_landmarks.npz" % name)
    np.savez_compressed(path, times_ms=times, pose=pose, hands=hands, blendshapes=blendshapes,
                        blendshape_names=np.array(["n%d" % i for i in range(52)]))
    job = {"protocol": 1, "tasks": [{"id": "video", "type": "vision", "input": "C:\\clips\\%s.mp4" % name,
                                     "pose": {"enabled": True}, "hands": {"enabled": False},
                                     "face": {"enabled": face_enabled}}]}
    (run_dir / "job.json").write_text(json.dumps(job), encoding="utf-8")
    return str(path)


def _write_audio(run_dir, frames=500, speech_frames=200):
    logprobs = np.full((frames, 5), -9.0, dtype=np.float16)
    logprobs[:, 0] = 0.0                       # blank
    logprobs[:speech_frames, 0] = -9.0
    logprobs[:speech_frames, 2] = 0.0          # a phoneme
    path = run_dir / "audio_speech_logits.npz"
    np.savez_compressed(path, logprobs=logprobs, frame_times=(np.arange(frames) + 0.5) * 0.02,
                        tokens=np.array(["<pad>", "a", "b", "c", "d"]), blank=0, frame_seconds=0.02)
    return str(path)


def test_service_is_not_instanced():
    with pytest.raises(RuntimeError):
        MocapSourceService()


def test_vision_output_is_described(tmp_path):
    info = MocapSourceService.inspect(_write_vision(_run_dir(tmp_path), frames=60, fps=30.0, face_frames=45))
    assert info["kind"] == _MODULE.KIND_VISION
    assert info["frames"] == 60
    assert abs(info["fps"] - 30.0) < 0.1
    assert abs(info["duration"] - 2.0) < 0.05
    assert info["detection"]["face"] == pytest.approx(0.75)
    assert "hands" not in info["detection"]  # disabled in job.json
    assert MocapSourceService.describe(info) == "front.mp4 · 23.10. 10:14"
    assert "face 75 %" in MocapSourceService.details(info)


def test_audio_output_is_described(tmp_path):
    info = MocapSourceService.inspect(_write_audio(_run_dir(tmp_path)))
    assert info["kind"] == _MODULE.KIND_AUDIO
    assert info["duration"] == pytest.approx(10.0)
    assert info["speech"] == pytest.approx(0.4)


def test_good_sources_have_no_problems(tmp_path):
    run_dir = _run_dir(tmp_path)
    vision = MocapSourceService.inspect(_write_vision(run_dir))
    audio = MocapSourceService.inspect(_write_audio(run_dir))
    assert MocapSourceService.check_role(vision, ROLE_FACE) == []
    assert MocapSourceService.check_role(vision, ROLE_BODY) == []
    assert MocapSourceService.check_role(audio, ROLE_AUDIO) == []


def test_wrong_kind_is_an_error(tmp_path):
    run_dir = _run_dir(tmp_path)
    vision = MocapSourceService.inspect(_write_vision(run_dir))
    audio = MocapSourceService.inspect(_write_audio(run_dir))
    assert MocapSourceService.check_role(audio, ROLE_FACE)[0][0] == ERROR
    assert MocapSourceService.check_role(audio, ROLE_BODY)[0][0] == ERROR
    assert MocapSourceService.check_role(vision, ROLE_AUDIO)[0][0] == ERROR


def test_detection_problems(tmp_path):
    none = MocapSourceService.inspect(_write_vision(_run_dir(tmp_path, "a"), face_frames=0))
    weak = MocapSourceService.inspect(_write_vision(_run_dir(tmp_path, "b"), face_frames=10))
    disabled = MocapSourceService.inspect(_write_vision(_run_dir(tmp_path, "c"), face_enabled=False))
    assert MocapSourceService.check_role(none, ROLE_FACE)[0][0] == ERROR
    assert MocapSourceService.check_role(weak, ROLE_FACE)[0][0] == WARNING
    assert "not enabled" in MocapSourceService.check_role(disabled, ROLE_FACE)[0][1]
    assert MocapSourceService.check_role(none, ROLE_BODY) == []  # the pose is fine


def test_missing_and_foreign_files(tmp_path):
    missing = MocapSourceService.inspect(str(tmp_path / "nope.npz"))
    assert MocapSourceService.check_role(missing, ROLE_BODY)[0] == (ERROR, "The file does not exist")
    foreign = tmp_path / "other.npz"
    np.savez(foreign, something=np.zeros(3))
    assert MocapSourceService.check_role(MocapSourceService.inspect(str(foreign)), ROLE_BODY)[0][0] == ERROR
    broken = tmp_path / "broken.npz"
    broken.write_bytes(b"not a zip")
    assert MocapSourceService.check_role(MocapSourceService.inspect(str(broken)), ROLE_BODY)[0][0] == ERROR


def test_inspection_follows_file_changes(tmp_path):
    run_dir = _run_dir(tmp_path)
    path = _write_vision(run_dir, face_frames=60)
    assert MocapSourceService.inspect(path)["detection"]["face"] == pytest.approx(1.0)
    _write_vision(run_dir, frames=61, face_frames=0)
    assert MocapSourceService.inspect(path)["detection"]["face"] == 0.0


def test_sources_with_different_fps_and_length_are_flagged(tmp_path):
    a = MocapSourceService.inspect(_write_vision(_run_dir(tmp_path, "a"), frames=60, fps=30.0))
    b = MocapSourceService.inspect(_write_vision(_run_dir(tmp_path, "b"), frames=50, fps=25.0))
    c = MocapSourceService.inspect(_write_vision(_run_dir(tmp_path, "c"), frames=150, fps=30.0))
    assert MocapSourceService.check_together(a, [a], None) == []
    messages = " ".join(message for _level, message in MocapSourceService.check_together(a, [b], None))
    assert "fps" in messages and "lengths" not in messages
    assert "lengths" in " ".join(message for _level, message in MocapSourceService.check_together(None, [a, c], None))


def test_latest_run_dir(tmp_path, monkeypatch):
    for name in ("20261023_090000", "20261024_101010", "20261023_235959"):
        (tmp_path / name).mkdir()
    monkeypatch.setattr(MocapSourceService, "get_runs_dir", staticmethod(lambda: str(tmp_path)))
    assert MocapSourceService.get_latest_run_dir() == os.path.join(str(tmp_path), "20261024_101010")


def _fake_run(tmp_path):
    """A run folder with two videos (face on the first), a third video which failed, and an audio task."""
    run_dir = _run_dir(tmp_path)
    tasks = [
        {"id": "video1", "type": "vision", "input": "front.mp4", "pose": {"enabled": True}, "face": {"enabled": True}},
        {"id": "video2", "type": "vision", "input": "side.mp4", "pose": {"enabled": True}, "face": {"enabled": False}},
        {"id": "video3", "type": "vision", "input": "broken.mp4", "pose": {"enabled": True}, "face": {"enabled": False}},
        {"id": "video10", "type": "vision", "input": "closeup.mp4", "pose": {"enabled": False}, "face": {"enabled": False}},
        {"id": "audio", "type": "audio", "input": "speech.wav"},
        ]
    (run_dir / "job.json").write_text(json.dumps({"protocol": 1, "tasks": tasks}), encoding="utf-8")
    for name in ("video1_front_landmarks.npz", "video2_side_landmarks.npz", "video10_closeup_landmarks.npz",
                 "video1_front_summary.txt", "audio_speech_logits.npz"):
        (run_dir / name).write_bytes(b"")
    return run_dir


def test_sources_from_run(tmp_path):
    run_dir = _fake_run(tmp_path)
    sources = MocapSourceService.sources_from_run(str(run_dir))
    assert sources["face"] == str(run_dir / "video1_front_landmarks.npz")
    # video3 failed (no file), video10 had no pose and must not be taken for video1
    assert sources["bodies"] == [str(run_dir / "video1_front_landmarks.npz"), str(run_dir / "video2_side_landmarks.npz")]
    assert sources["audio"] == str(run_dir / "audio_speech_logits.npz")


def test_sources_from_run_without_job(tmp_path):
    assert MocapSourceService.sources_from_run(str(tmp_path)) == {"face": None, "bodies": [], "audio": None}


ARKIT_FACEUNITS = dynamic_import("mpfb.services.faceservice", "ARKIT_FACEUNITS")
_ROTATIONS = ["HeadYaw", "HeadPitch", "HeadRoll", "LeftEyeYaw", "LeftEyePitch", "LeftEyeRoll",
              "RightEyeYaw", "RightEyePitch", "RightEyeRoll"]


def _write_livelink(path, frames=120, empty=False):
    """A csv as Live Link Face writes it: Timecode, BlendShapeCount, the ARKit names capitalized, head and eye rotation.
    The timecode starts just before a full second at 60 fps, one row is repeated."""
    names = [name[0].upper() + name[1:] for name in ARKIT_FACEUNITS]
    lines = [",".join(["Timecode", "BlendShapeCount"] + names + _ROTATIONS)]
    for frame in range(frames):
        total = 57 + frame
        timecode = "10:20:%02d:%02d.%03d" % (30 + total // 60, total % 60, 125)
        values = [0.0] * len(names) if empty else [0.5 if name == "JawOpen" else 0.1 for name in names]
        row = [timecode, str(len(names))] + ["%.4f" % value for value in values] + ["0.01"] * len(_ROTATIONS)
        lines.append(",".join(row))
        if frame == 10:
            lines.append(",".join(row))
    path.write_text("\n".join(lines) + "\n", encoding="utf-8")
    return str(path)


def test_livelink_csv_is_read(tmp_path):
    times, names, values = MocapSourceService.read_livelink_csv(_write_livelink(tmp_path / "take.csv"))
    assert len(times) == 120  # the repeated row is dropped
    assert times[0] == 0.0
    assert times[1] == pytest.approx(1.0 / 60.0)
    assert times[-1] == pytest.approx(119.0 / 60.0)
    assert sorted(names) == sorted(ARKIT_FACEUNITS)
    assert "tongueOut" in names and "HeadYaw" not in names
    assert values[0, names.index("jawOpen")] == pytest.approx(0.5)


def test_livelink_csv_as_face_source(tmp_path):
    info = MocapSourceService.inspect(_write_livelink(tmp_path / "take.csv"))
    assert info["kind"] == _MODULE.KIND_LIVELINK
    assert abs(info["fps"] - 60.0) < 0.1
    assert MocapSourceService.describe(info) == "take.csv"
    assert "Live Link Face" in MocapSourceService.details(info)
    assert MocapSourceService.check_role(info, ROLE_FACE) == []
    assert MocapSourceService.check_role(info, ROLE_BODY)[0][0] == ERROR
    assert MocapSourceService.check_role(info, ROLE_AUDIO)[0][0] == ERROR


def test_empty_or_foreign_csv_is_rejected(tmp_path):
    empty = MocapSourceService.inspect(_write_livelink(tmp_path / "empty.csv", empty=True))
    assert MocapSourceService.check_role(empty, ROLE_FACE)[0][0] == ERROR
    foreign = tmp_path / "other.csv"
    foreign.write_text("a,b\n1,2\n", encoding="utf-8")
    assert MocapSourceService.check_role(MocapSourceService.inspect(str(foreign)), ROLE_FACE)[0][0] == ERROR
